import { SVG_NS, XLINK_NS } from "../types"

export function parseSvg(xml: string): XMLDocument {
  // A detached XML document is the authoring source; preview rendering is a separate concern.
  if (/<!\s*ENTITY\b/i.test(xml) || /<!DOCTYPE[^>]*\[/i.test(xml))
    throw new Error("SVG entity declarations are not supported.")
  const doc = new DOMParser().parseFromString(xml, "image/svg+xml")
  if (
    doc.querySelector("parsererror") ||
    doc.documentElement.localName !== "svg" ||
    doc.documentElement.namespaceURI !== SVG_NS
  )
    throw new Error("The file is not a valid SVG document.")
  return doc
}
export const serializeSvg = (doc: XMLDocument) => new XMLSerializer().serializeToString(doc)
export function nodes(root: Node): Node[] {
  const result: Node[] = [],
    stack = [root]
  while (stack.length) {
    const node = stack.pop()!
    result.push(node)
    for (let i = node.childNodes.length - 1; i >= 0; i--) stack.push(node.childNodes[i])
  }
  return result
}
export const isElement = (node: Node | null | undefined): node is Element => node?.nodeType === 1
export function writeAttribute(element: Element, name: string, value: string | null) {
  if (!/^[A-Za-z_][\w.:-]*$/.test(name)) throw new Error("Invalid XML attribute name.")
  let ns: string | null = null
  if (name === "xmlns" || name.startsWith("xmlns:")) ns = "http://www.w3.org/2000/xmlns/"
  else if (name.startsWith("xml:")) ns = "http://www.w3.org/XML/1998/namespace"
  else if (name.startsWith("xlink:")) ns = XLINK_NS
  else if (name.includes(":")) {
    ns = element.lookupNamespaceURI(name.split(":")[0])
    if (!ns) throw new Error("Declare the XML namespace before using this attribute.")
  }
  const local = name.includes(":") ? name.split(":")[1] : name
  if (value === null) {
    if (ns) element.removeAttributeNS(ns, local)
    else element.removeAttribute(name)
  } else if (ns) element.setAttributeNS(ns, name, value)
  else element.setAttribute(name, value)
}
/** Scripts stay inert in the isolated preview; original unsupported XML survives export. */
export function previewClone(root: Element, key: (node: Node) => string): SVGSVGElement {
  const clone = root.cloneNode(true) as SVGSVGElement
  const original = nodes(root),
    copies = nodes(clone)
  original.forEach((node, index) => {
    const copy = copies[index]
    if (!isElement(copy)) return
    copy.setAttribute("data-svg-editor-key", key(node))
    if (
      [
        "script",
        "foreignObject",
        "iframe",
        "object",
        "embed",
        "animate",
        "animateTransform",
        "animateMotion",
        "set",
      ].includes(copy.localName)
    ) {
      copy.remove()
      return
    }
    for (const attr of Array.from(copy.attributes)) {
      if (
        /^on/i.test(attr.name) ||
        ((attr.localName === "href" || attr.name === "src") &&
          /^\s*(?:javascript|vbscript):/i.test(attr.value))
      )
        copy.removeAttributeNode(attr)
    }
  })
  return clone
}
