import type { Point } from "../types"
export const mix = (a: Point, b: Point, t: number): Point => ({
  x: a.x + (b.x - a.x) * t,
  y: a.y + (b.y - a.y) * t,
})
export const distance2 = (a: Point, b: Point) => (a.x - b.x) ** 2 + (a.y - b.y) ** 2
export const point = (values: number[], offset = values.length - 2): Point => ({
  x: values[offset],
  y: values[offset + 1],
})
export const numberText = (value: number) => {
  if (!Number.isFinite(value)) throw new Error("Coordinates must be finite numbers.")
  return String(Math.round(value * 1e8) / 1e8)
}
export function cubic(a: Point, b: Point, c: Point, d: Point, t: number): Point {
  return mix(mix(mix(a, b, t), mix(b, c, t), t), mix(mix(b, c, t), mix(c, d, t), t), t)
}
export function quadratic(a: Point, b: Point, c: Point, t: number): Point {
  return mix(mix(a, b, t), mix(b, c, t), t)
}
export function lineProjection(a: Point, b: Point, p: Point) {
  const length = distance2(a, b)
  return length
    ? Math.max(0, Math.min(1, ((p.x - a.x) * (b.x - a.x) + (p.y - a.y) * (b.y - a.y)) / length))
    : 0
}
export class SnapIndex {
  private buckets = new Map<string, Point[]>()
  constructor(
    private radius: number,
    points: Point[],
  ) {
    for (const p of points) {
      const key = this.key(p)
      this.buckets.set(key, [...(this.buckets.get(key) || []), p])
    }
  }
  private key(p: Point) {
    return `${Math.floor(p.x / this.radius)},${Math.floor(p.y / this.radius)}`
  }
  nearest(p: Point): Point {
    let best = p,
      distance = this.radius ** 2
    const x = Math.floor(p.x / this.radius),
      y = Math.floor(p.y / this.radius)
    for (let dx = -1; dx <= 1; dx++)
      for (let dy = -1; dy <= 1; dy++) {
        for (const candidate of this.buckets.get(`${x + dx},${y + dy}`) || []) {
          const next = distance2(candidate, p)
          if (next < distance) {
            best = candidate
            distance = next
          }
        }
      }
    return { ...best }
  }
}
