import type { Point } from "../types"
/** SVG endpoint-to-center conversion; radii correction follows SVG 2 implementation notes. */
export function arcGeometry(start: Point, values: number[]) {
  let [rx, ry, rotation, large, sweep, x, y] = values
  rx = Math.abs(rx)
  ry = Math.abs(ry)
  if (!rx || !ry || (start.x === x && start.y === y)) return null
  const phi = (rotation * Math.PI) / 180,
    cos = Math.cos(phi),
    sin = Math.sin(phi)
  const dx = (start.x - x) / 2,
    dy = (start.y - y) / 2
  const px = cos * dx + sin * dy,
    py = -sin * dx + cos * dy
  const correction = px ** 2 / rx ** 2 + py ** 2 / ry ** 2
  if (correction > 1) {
    rx *= Math.sqrt(correction)
    ry *= Math.sqrt(correction)
  }
  const factor =
    (large === sweep ? -1 : 1) *
    Math.sqrt(
      Math.max(
        0,
        (rx ** 2 * ry ** 2 - rx ** 2 * py ** 2 - ry ** 2 * px ** 2) /
          (rx ** 2 * py ** 2 + ry ** 2 * px ** 2),
      ),
    )
  const cxp = (factor * rx * py) / ry,
    cyp = (-factor * ry * px) / rx
  const cx = cos * cxp - sin * cyp + (start.x + x) / 2,
    cy = sin * cxp + cos * cyp + (start.y + y) / 2
  const ux = (px - cxp) / rx,
    uy = (py - cyp) / ry,
    vx = (-px - cxp) / rx,
    vy = (-py - cyp) / ry
  const theta = Math.atan2(uy, ux)
  let delta = Math.atan2(ux * vy - uy * vx, ux * vx + uy * vy)
  if (!sweep && delta > 0) delta -= 2 * Math.PI
  if (sweep && delta < 0) delta += 2 * Math.PI
  return {
    rx,
    ry,
    rotation,
    sweep,
    theta,
    delta,
    at: (t: number): Point => {
      const angle = theta + delta * t
      return {
        x: cx + cos * rx * Math.cos(angle) - sin * ry * Math.sin(angle),
        y: cy + sin * rx * Math.cos(angle) + cos * ry * Math.sin(angle),
      }
    },
  }
}
