import type { Handle, Point } from "../types"
import { arcGeometry } from "./arc"
import { cubic, distance2, lineProjection, mix, numberText, point, quadratic } from "./math"
export type Segment = { type: "M" | "L" | "C" | "Q" | "A" | "Z"; values: number[] }
const arities: Record<string, number> = { M: 2, L: 2, H: 1, V: 1, C: 6, S: 4, Q: 4, T: 2, A: 7 }
/** Absolute commands, retaining true arcs/curves and compound subpaths. No browser polyfill. */
export function parsePath(source: string): Segment[] {
  let index = 0,
    command = "",
    cursor: Point = { x: 0, y: 0 },
    start = cursor,
    previous = "",
    control = cursor
  const result: Segment[] = []
  const skip = () => {
    while (/[\s,]/.test(source[index] ?? "") && index < source.length) index++
  }
  const read = (flag = false) => {
    skip()
    const match = flag
      ? /^[01]/.exec(source.slice(index))
      : /^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/.exec(source.slice(index))
    if (!match) throw new Error(`Invalid path data at character ${index + 1}.`)
    index += match[0].length
    const value = Number(match[0])
    if (!Number.isFinite(value)) throw new Error("Path coordinates must be finite.")
    return value
  }
  while (true) {
    skip()
    if (index >= source.length) break
    if (/[a-z]/i.test(source[index])) command = source[index++]
    else if (!command || command.toUpperCase() === "Z")
      throw new Error(`Expected a path command at character ${index + 1}.`)
    const type = command.toUpperCase(),
      relative = command !== type
    if (!result.length && type !== "M") throw new Error("A path must start with M.")
    if (type === "Z") {
      result.push({ type: "Z", values: [] })
      cursor = { ...start }
      previous = "Z"
      command = ""
      continue
    }
    if (!arities[type]) throw new Error(`Unknown path command ${command}.`)
    const v = Array.from({ length: arities[type] }, (_, i) =>
      read(type === "A" && (i === 3 || i === 4)),
    )
    const absolute = (offset: number) => {
      if (relative) {
        v[offset] += cursor.x
        v[offset + 1] += cursor.y
      }
    }
    let segment: Segment
    if (type === "H") segment = { type: "L", values: [v[0] + (relative ? cursor.x : 0), cursor.y] }
    else if (type === "V")
      segment = { type: "L", values: [cursor.x, v[0] + (relative ? cursor.y : 0)] }
    else if (type === "A") {
      absolute(5)
      segment = { type, values: [Math.abs(v[0]), Math.abs(v[1]), ...v.slice(2)] }
    } else {
      for (let i = 0; i < v.length; i += 2) absolute(i)
      const reflected =
        previous === (type === "S" ? "C" : "Q")
          ? { x: 2 * cursor.x - control.x, y: 2 * cursor.y - control.y }
          : cursor
      if (type === "S") segment = { type: "C", values: [reflected.x, reflected.y, ...v] }
      else if (type === "T") segment = { type: "Q", values: [reflected.x, reflected.y, ...v] }
      else segment = { type: type as Segment["type"], values: v }
    }
    result.push(segment)
    cursor = point(segment.values)
    if (segment.type === "M") start = { ...cursor }
    control =
      segment.type === "C"
        ? point(segment.values, 2)
        : segment.type === "Q"
          ? point(segment.values, 0)
          : cursor
    previous = segment.type
    if (type === "M") command = relative ? "l" : "L"
  }
  return result
}
export const serializePath = (segments: Segment[]) =>
  segments.map(({ type, values }) => `${type}${values.map(numberText).join(" ")}`).join(" ")
export function segmentPositions(segments: Segment[]) {
  let cursor: Point = { x: 0, y: 0 },
    start = cursor
  return segments.map((segment) => {
    const from = { ...cursor }
    if (segment.type === "M") start = point(segment.values)
    cursor = segment.type === "Z" ? { ...start } : point(segment.values)
    return { from, to: { ...cursor } }
  })
}
export function pathHandles(segments: Segment[]): Handle[] {
  const positions = segmentPositions(segments),
    handles: Handle[] = []
  segments.forEach((segment, i) => {
    if (segment.type === "Z") return
    const last = segment.values.length - 2
    handles.push({ segment: i, offset: last, point: point(segment.values), kind: "anchor" })
    if (segment.type === "C") {
      handles.push({
        segment: i,
        offset: 0,
        point: point(segment.values, 0),
        kind: "control",
        anchor: positions[i].from,
      })
      handles.push({
        segment: i,
        offset: 2,
        point: point(segment.values, 2),
        kind: "control",
        anchor: positions[i].to,
      })
    } else if (segment.type === "Q")
      handles.push({
        segment: i,
        offset: 0,
        point: point(segment.values, 0),
        kind: "control",
        anchor: positions[i].from,
      })
  })
  return handles
}
export function moveHandle(segments: Segment[], handle: Handle, destination: Point): Segment[] {
  const next = segments.map((s) => ({ ...s, values: [...s.values] })),
    segment = next[handle.segment]
  const dx = destination.x - segment.values[handle.offset],
    dy = destination.y - segment.values[handle.offset + 1]
  const translate = (s: Segment, offset: number) => {
    s.values[offset] += dx
    s.values[offset + 1] += dy
  }
  translate(segment, handle.offset)
  if (handle.kind === "anchor") {
    if (segment.type === "C") translate(segment, 2)
    if (segment.type === "Q") translate(segment, 0)
    const following = next[handle.segment + 1]
    if (following?.type === "C") translate(following, 0)
    // A closing cubic's control belongs to the move-to anchor of this subpath.
    if (segment.type === "M") {
      let end = handle.segment + 1
      while (end < next.length && next[end].type !== "M") end++
      if (next[end - 1]?.type === "Z") {
        const last = next[end - 2]
        const original = segments[end - 2]
        if (
          last &&
          last.type !== "Z" &&
          original &&
          distance2(point(original.values), handle.point) < 1e-16
        ) {
          translate(last, last.values.length - 2)
          if (last.type === "C") translate(last, 2)
        }
      }
    }
  }
  return next
}
export function atSegment(segment: Segment, from: Point, to: Point, t: number): Point {
  if (segment.type === "C")
    return cubic(from, point(segment.values, 0), point(segment.values, 2), to, t)
  if (segment.type === "Q") return quadratic(from, point(segment.values, 0), to, t)
  if (segment.type === "A") return arcGeometry(from, segment.values)?.at(t) ?? mix(from, to, t)
  return mix(from, to, t)
}
export function nearestSegment(segments: Segment[], target: Point) {
  let best = { segment: -1, t: 0, distance: Infinity, point: target }
  const positions = segmentPositions(segments)
  segments.forEach((s, i) => {
    if (s.type === "M") return
    const { from, to } = positions[i]
    let t: number
    if (s.type === "L" || s.type === "Z") t = lineProjection(from, to, target)
    else {
      // Bounded work per segment, independent of path length or zoom level.
      let sample = 0,
        d = Infinity
      for (let k = 0; k <= 24; k++) {
        const next = distance2(atSegment(s, from, to, k / 24), target)
        if (next < d) {
          d = next
          sample = k / 24
        }
      }
      let lo = Math.max(0, sample - 1 / 24),
        hi = Math.min(1, sample + 1 / 24)
      for (let k = 0; k < 18; k++) {
        const a = lo + (hi - lo) / 3,
          b = hi - (hi - lo) / 3
        if (
          distance2(atSegment(s, from, to, a), target) <
          distance2(atSegment(s, from, to, b), target)
        )
          hi = b
        else lo = a
      }
      t = (lo + hi) / 2
    }
    const p = atSegment(s, from, to, t),
      distance = distance2(p, target)
    if (distance < best.distance) best = { segment: i, t, distance, point: p }
  })
  return best
}
export function splitSegment(segments: Segment[], index: number, t: number): Segment[] {
  if (!(t > 0 && t < 1) || !segments[index] || segments[index].type === "M") return segments
  const next = segments.map((s) => ({ ...s, values: [...s.values] })),
    s = next[index],
    { from, to } = segmentPositions(next)[index]
  let parts: Segment[]
  const pair = (p: Point) => [p.x, p.y]
  if (s.type === "C") {
    const a = mix(from, point(s.values, 0), t),
      b = mix(point(s.values, 0), point(s.values, 2), t),
      c = mix(point(s.values, 2), to, t)
    const d = mix(a, b, t),
      e = mix(b, c, t),
      p = mix(d, e, t)
    parts = [
      { type: "C", values: [...pair(a), ...pair(d), ...pair(p)] },
      { type: "C", values: [...pair(e), ...pair(c), ...pair(to)] },
    ]
  } else if (s.type === "Q") {
    const a = mix(from, point(s.values, 0), t),
      b = mix(point(s.values, 0), to, t),
      p = mix(a, b, t)
    parts = [
      { type: "Q", values: [...pair(a), ...pair(p)] },
      { type: "Q", values: [...pair(b), ...pair(to)] },
    ]
  } else if (s.type === "A" && arcGeometry(from, s.values)) {
    const arc = arcGeometry(from, s.values)!,
      p = arc.at(t)
    const values = (portion: number, end: Point) => [
      arc.rx,
      arc.ry,
      arc.rotation,
      Math.abs(arc.delta * portion) > Math.PI ? 1 : 0,
      arc.sweep,
      ...pair(end),
    ]
    parts = [
      { type: "A", values: values(t, p) },
      { type: "A", values: values(1 - t, to) },
    ]
  } else
    parts = [
      { type: "L", values: pair(mix(from, to, t)) },
      s.type === "Z" ? { type: "Z", values: [] } : { type: "L", values: pair(to) },
    ]
  next.splice(index, 1, ...parts)
  return next
}
export function deleteAnchor(segments: Segment[], index: number): Segment[] {
  if (!segments[index] || segments[index].type === "Z") return segments
  const next = segments.map((s) => ({ ...s, values: [...s.values] }))
  if (next[index].type === "M") {
    const following = next[index + 1]
    if (following && following.type !== "M" && following.type !== "Z")
      next[index + 1] = { type: "M", values: [...following.values.slice(-2)] }
    else if (following?.type === "Z") next.splice(index + 1, 1)
  }
  next.splice(index, 1)
  return next
}
export function parsePoints(source: string): Point[] {
  if (!source.trim()) return []
  const values = source
    .trim()
    .split(/[\s,]+/)
    .map(Number)
  if (values.length % 2 || values.some((v) => !Number.isFinite(v)))
    throw new Error("Use pairs of finite x,y coordinates.")
  return Array.from({ length: values.length / 2 }, (_, i) => ({
    x: values[i * 2],
    y: values[i * 2 + 1],
  }))
}
export const serializePoints = (points: Point[]) =>
  points.map((p) => `${numberText(p.x)},${numberText(p.y)}`).join(" ")
