export const SVG_NS = "http://www.w3.org/2000/svg"
export const XLINK_NS = "http://www.w3.org/1999/xlink"
export type Point = { x: number; y: number }
export type Bounds = Point & { width: number; height: number }
export type RegionPredicate = (element: Element) => boolean
export type EditorState = Readonly<{
  revision: number
  selected: string | null
  canUndo: boolean
  canRedo: boolean
  dirty: boolean
}>
export type TreeEntry = {
  key: string
  name: string
  id: string
  text: string
  region: boolean
  children: TreeEntry[]
  parent: string | null
}
export type EditorSnapshot = { xml: string; keys: string[]; selected: string | null }
export type Tool = "select" | "hand" | "draw"
export type Handle = {
  segment: number
  offset: number
  point: Point
  kind: "anchor" | "control"
  anchor?: Point
}
